command:
// Lantern Night in Hallowby: a new Easy raid, with Hallowby's shopping list on the Raid HUD.
// Run it as the Storyteller once each player owns their Entity: the raid takes every Entity with a player owner.
return game.dontGetForked.raid.start({
  town: "Hallowby", difficulty: "easy",
  list: [
    { name: "a cask of red wine", duty: "cook", essential: true },
    { name: "a pot of nightshade", duty: "gardener", essential: false },
    { name: "a set of new hinges", duty: "handyman", essential: false },
    { name: "a new cape", duty: "tailor", essential: false }
  ],
});
